4	const USAGE: &str = "
5	Usage: mergesort bench [--size N]
6	       mergesort --help
7	
8	Parallel mergesort: regular sorting with a parallel merge step.
9	O(n log n) time; O(n) extra space; critical path is O(log^3 n)
10	
11	Algorithm described in: https://software.intel.com/en-us/articles/a-parallel-stable-sort-using-c11-for-tbb-cilk-plus-and-openmp
12	
13	Commands:
14	    bench              Run the benchmark in different modes and print the timings.
15	
16	Options:
17	    --size N           Number of 32-bit words to sort [default: 250000000] (1GB)
18	    -h, --help         Show this message.
19	";
20	
21	#[derive(serde::Deserialize)]
22	pub struct Args {
23	    cmd_bench: bool,
24	    flag_size: usize,
25	}
26	
27	use docopt::Docopt;
28	
29	use std::mem::MaybeUninit;
30	use std::slice;
31	use std::time::Instant;
32	
33	pub fn merge_sort<T: Ord + Send + Copy>(v: &mut [T]) {
34	    let n = v.len();
35	    let mut buf: Vec<MaybeUninit<T>> = Vec::with_capacity(n);
36	    // SAFETY: MaybeUninit can be uninitialized
37	    unsafe {
38	        buf.set_len(n);
39	    }
40	    rsort(v, &mut buf[..]);
41	}
42	
43	// Values from manual tuning gigasort on one machine.
44	const SORT_CHUNK: usize = 32 * 1024;
45	const MERGE_CHUNK: usize = 64 * 1024;
46	
47	fn as_uninit_slice<T: Copy>(slice: &[T]) -> &[MaybeUninit<T>] {
48	    let len = slice.len();
49	    // SAFETY: MaybeUninit is transparent to T, and we're only dealing with T: Copy
50	    unsafe { slice::from_raw_parts(slice.as_ptr().cast(), len) }
51	}
52	
53	fn as_uninit_slice_mut<T: Copy>(slice: &mut [T]) -> &mut [MaybeUninit<T>] {
54	    let len = slice.len();
55	    // SAFETY: MaybeUninit is transparent to T, and we're only dealing with T: Copy
56	    unsafe { slice::from_raw_parts_mut(slice.as_mut_ptr().cast(), len) }
57	}
58	
59	unsafe fn slice_assume_init_mut<T>(slice: &mut [MaybeUninit<T>]) -> &mut [T] {
60	    let len = slice.len();
61	    unsafe { slice::from_raw_parts_mut(slice.as_mut_ptr().cast(), len) }
62	}
63	
64	// Sort src, possibly making use of identically sized buf.
65	fn rsort<T: Ord + Send + Copy>(src: &mut [T], buf: &mut [MaybeUninit<T>]) {
66	    if src.len() <= SORT_CHUNK {
67	        src.sort();
68	        return;
69	    }
70	
71	    // Sort each half into half of the buffer.
72	    let mid = src.len() / 2;
73	    let (sa, sb) = src.split_at_mut(mid);
74	    let (bufa, bufb) = buf.split_at_mut(mid);
75	    let (sorta, sortb) = rayon::join(|| rsort_into(sa, bufa), || rsort_into(sb, bufb));
76	
77	    // Merge the buffer halves back into the original.
78	    rmerge(sorta, sortb, as_uninit_slice_mut(src));
79	}
80	
81	// Sort src, putting the result into dest.
82	fn rsort_into<'dest, T: Ord + Send + Copy>(
83	    src: &mut [T],
84	    dest: &'dest mut [MaybeUninit<T>],
85	) -> &'dest mut [T] {
86	    let mid = src.len() / 2;
87	    let (s1, s2) = src.split_at_mut(mid);
88	    {
89	        // Sort each half.
90	        let (d1, d2) = dest.split_at_mut(mid);
91	        rayon::join(|| rsort(s1, d1), || rsort(s2, d2));
92	    }
93	
94	    // Merge the halves into dest.
95	    rmerge(s1, s2, dest);
96	    unsafe { slice_assume_init_mut(dest) }
97	}
98	
99	// Merge sorted inputs a and b, putting result in dest.
100	//
101	// Note: `a` and `b` have type `&mut [T]` and not `&[T]` because we do
102	// not want to require a `T: Sync` bound. Using `&mut` references
103	// proves to the compiler that we are not sharing `a` and `b` across
104	// threads and thus we only need a `T: Send` bound.
105	fn rmerge<T: Ord + Send + Copy>(a: &mut [T], b: &mut [T], dest: &mut [MaybeUninit<T>]) {
106	    // Swap so a is always longer.
107	    let (a, b) = if a.len() > b.len() { (a, b) } else { (b, a) };
108	    if dest.len() <= MERGE_CHUNK {
109	        seq_merge(a, b, dest);
110	        return;
111	    }
112	
113	    // Find the middle element of the longer list, and
114	    // use binary search to find its location in the shorter list.
115	    let ma = a.len() / 2;
116	    let mb = match b.binary_search(&a[ma]) {
117	        Ok(i) => i,
118	        Err(i) => i,
119	    };
120	
121	    let (a1, a2) = a.split_at_mut(ma);
122	    let (b1, b2) = b.split_at_mut(mb);
123	    let (d1, d2) = dest.split_at_mut(ma + mb);
124	    rayon::join(|| rmerge(a1, b1, d1), || rmerge(a2, b2, d2));
125	}
126	
127	// Merges sorted a and b into sorted dest.
128	#[inline(never)]
129	fn seq_merge<T: Ord + Copy>(a: &[T], b: &[T], dest: &mut [MaybeUninit<T>]) {
130	    if b.is_empty() {
131	        dest.copy_from_slice(as_uninit_slice(a));
132	        return;
133	    }
134	    let biggest = Ord::max(*a.last().unwrap(), *b.last().unwrap());
135	    let mut ai = a.iter();
136	    let mut an = *ai.next().unwrap();
137	    let mut bi = b.iter();
138	    let mut bn = *bi.next().unwrap();
139	    for d in dest.iter_mut() {
140	        if an < bn {
141	            *d = MaybeUninit::new(an);
142	            an = match ai.next() {
143	                Some(x) => *x,
144	                None => biggest,
145	            }
146	        } else {
147	            *d = MaybeUninit::new(bn);
148	            bn = match bi.next() {
149	                Some(x) => *x,
150	                None => biggest,
151	            }
152	        }
153	    }
154	}
155	
156	#[test]
157	fn test_merge_sort() {
158	    let mut v = vec![1; 200_000];
159	    merge_sort(&mut v[..]);
160	
161	    let sorted: Vec<u32> = (1..1_000_000).collect();
162	    let mut v = sorted.clone();
163	    merge_sort(&mut v[..]);
164	    assert_eq!(sorted, v);
165	
166	    v.reverse();
167	    merge_sort(&mut v[..]);
168	    assert_eq!(sorted, v);
169	}
170	
171	pub fn seq_merge_sort<T: Ord + Copy>(v: &mut [T]) {
172	    let n = v.len();
173	    let mut buf: Vec<MaybeUninit<T>> = Vec::with_capacity(n);
174	    // SAFETY: MaybeUninit can be uninitialized
175	    unsafe {
176	        buf.set_len(n);
177	    }
178	    seq_sort(v, &mut buf[..]);
179	}
180	
181	// Sort src, possibly making use of identically sized buf.
182	fn seq_sort<T: Ord + Copy>(src: &mut [T], buf: &mut [MaybeUninit<T>]) {
183	    if src.len() <= SORT_CHUNK {
184	        src.sort();
185	        return;
186	    }
187	
188	    // Sort each half into half of the buffer.
189	    let mid = src.len() / 2;
190	    let (sa, sb) = src.split_at_mut(mid);
191	    let (bufa, bufb) = buf.split_at_mut(mid);
192	    let (sorta, sortb) = (seq_sort_into(sa, bufa), seq_sort_into(sb, bufb));
193	
194	    // Merge the buffer halves back into the original.
195	    seq_merge(sorta, sortb, as_uninit_slice_mut(src));
196	}
197	
198	// Sort src, putting the result into dest.
199	fn seq_sort_into<'dest, T: Ord + Copy>(
200	    src: &mut [T],
201	    dest: &'dest mut [MaybeUninit<T>],
202	) -> &'dest mut [T] {
203	    let mid = src.len() / 2;
204	    let (s1, s2) = src.split_at_mut(mid);
205	    {
206	        // Sort each half.
207	        let (d1, d2) = dest.split_at_mut(mid);
208	        seq_sort(s1, d1);
209	        seq_sort(s2, d2);
210	    }
211	
212	    // Merge the halves into dest.
213	    seq_merge(s1, s2, dest);
214	    unsafe { slice_assume_init_mut(dest) }
215	}
216	
217	pub fn is_sorted<T: Send + Ord>(v: &mut [T]) -> bool {
218	    let n = v.len();
219	    if n <= SORT_CHUNK {
220	        for i in 1..n {
221	            if v[i - 1] > v[i] {
222	                return false;
223	            }
224	        }
225	        return true;
226	    }
227	
228	    let mid = n / 2;
229	    if v[mid - 1] > v[mid] {
230	        return false;
231	    }
232	    let (a, b) = v.split_at_mut(mid);
233	    let (left, right) = rayon::join(|| is_sorted(a), || is_sorted(b));
234	    left && right
235	}
236	
237	fn default_vec(n: usize) -> Vec<u32> {
238	    let rng = crate::seeded_rng();
239	    rng.sample_iter(&StandardUniform).take(n).collect()
240	}
241	
242	fn timed_sort<F: FnOnce(&mut [u32])>(n: usize, f: F, name: &str) -> u64 {
243	    let mut v = default_vec(n);
244	
245	    let start = Instant::now();
246	    f(&mut v[..]);
247	    let dur = Instant::now() - start;
248	    let nanos = u64::from(dur.subsec_nanos()) + dur.as_secs() * 1_000_000_000u64;
249	    println!("{}: sorted {} ints: {} s", name, n, nanos as f32 / 1e9f32);
250	
251	    // Check correctness
252	    assert!(is_sorted(&mut v[..]));
253	
254	    nanos
255	}
256	
257	pub fn main(args: &[String]) {
258	    let args: Args = Docopt::new(USAGE)
259	        .and_then(|d| d.argv(args).deserialize())
260	        .unwrap_or_else(|e| e.exit());
261	
262	    if args.cmd_bench {
263	        let seq = timed_sort(args.flag_size, seq_merge_sort, "seq");
264	        let par = timed_sort(args.flag_size, merge_sort, "par");
265	        let speedup = seq as f64 / par as f64;
266	        println!("speedup: {speedup:.2}x");
267	    }
268	}
269	
